// CloudWatch Synthetics canary: checks the deployed API from outside AWS's network
// every few minutes. A failed step marks the run failed, which fires the canary alarm.
const synthetics = require('Synthetics');

const base = new URL(process.env.API_URL);

async function readBody(res) {
  return new Promise((resolve, reject) => {
    let data = '';
    res.on('data', (chunk) => { data += chunk; });
    res.on('end', () => resolve(data));
    res.on('error', reject);
  });
}

async function checkJson(path, verify) {
  const request = {
    hostname: base.hostname,
    method: 'GET',
    path,
    port: 443,
    protocol: 'https:',
    headers: { 'User-Agent': synthetics.getCanaryUserAgentString() },
  };
  await synthetics.executeHttpStep(`GET ${path}`, request, async (res) => {
    if (res.statusCode !== 200) {
      throw new Error(`${path} returned HTTP ${res.statusCode}`);
    }
    verify(JSON.parse(await readBody(res)));
  });
}

exports.handler = async () => {
  await checkJson('/health', (body) => {
    if (body.status !== 'ok') throw new Error(`status is ${body.status}`);
    // "mock" means DynamoDB is unreachable and the app is serving sample data.
    if (body.data_source !== 'dynamodb') throw new Error(`data_source is ${body.data_source}`);
    if (body.ml?.transcribe !== 'real') throw new Error(`transcribe is ${body.ml?.transcribe}`);
    if (body.ml?.pronunciation !== 'real') {
      throw new Error(`pronunciation is ${body.ml?.pronunciation}`);
    }
  });
  await checkJson('/api/categories', (body) => {
    if (!body.categories?.length) throw new Error('no categories returned');
  });
};
